// The post-appointment pause is a per-company policy from the central store,
// changed only by a Lexia admin. It is the same for WhatsApp, Instagram and
// Messenger and applies only to the conversation where the appointment was
// confirmed; other conversations of the same lead are never paused.
const scenarios = [true, false].map(pause => ({
  pause_after_appointment: pause,
  appointment_block_created: pause,
  single_confirmation_allowed: true,
  replies_after_confirmation_blocked: pause,
  other_blocks_still_apply: true,
  other_conversations_of_lead_paused: false,
}));
const cancelled = { appointment_status: 'cancelled', block_kept_until_original_end: true, reminder_allowed: false };
const removed = { block_removed_manually: true, reminder_allowed_before_start: true, reminder_allowed_after_start: false };
return [{ json: { scenarios, cancelled, removed, simulated: true } }];
